-- KAD4 2026-11-02 | DESIGN CANDIDATE ONLY: DO NOT EXECUTE ON PRODUCTION.
-- MAIN SHA db21cefcc09c6bcb5d7e3fca16d100cc0accd13d ; source schema read-only verified.
-- Migration filename MUST be generated by supabase CLI in authorized engineering phase.
-- All rights, policy, D/G activation and project membership must be independently tested.
-- Project identity decision: existing public.research_tasks only has task/Owner, no stable project table.
-- CREATE studio.projects as canonical project identity, with Owner-only access until verified
-- authorized collaborator/membership model; no unrestricted project_ref strings.

CREATE SCHEMA IF NOT EXISTS studio;
CREATE SCHEMA IF NOT EXISTS experience;
CREATE SCHEMA IF NOT EXISTS participation;
CREATE SCHEMA IF NOT EXISTS culture;
REVOKE ALL ON SCHEMA studio,experience,participation,culture FROM PUBLIC, anon, authenticated;

CREATE TABLE studio.projects (
  project_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  owner_user_id uuid NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
  project_title text NOT NULL,
  research_scope jsonb NOT NULL DEFAULT '{}'::jsonb,
  lifecycle_status text NOT NULL DEFAULT 'ACTIVE',
  created_at timestamptz NOT NULL DEFAULT now(),
  archived_at timestamptz
);
-- Only project.owner_user_id can access a project initially; cross-project reuse requires
-- source-project grant and destination-project grant, not a shared subject name.

CREATE TABLE studio.asset_heads (
  asset_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES studio.projects(project_id) ON DELETE RESTRICT,
  owner_user_id uuid REFERENCES public.users(user_id) ON DELETE RESTRICT,
  asset_kind text NOT NULL CHECK (asset_kind IN
    ('research_brief','source_anchor','reading_note','evidence_note','spacetime_candidate',
     'relation_hypothesis','humanistic_insight','research_collection','director_plan',
     'media_selection','work_revision','citation_snapshot','consented_feedback')),
  current_revision_id uuid,
  access_state text NOT NULL DEFAULT 'PROJECT_RESTRICTED',
  created_at timestamptz NOT NULL DEFAULT now(),
  archived_at timestamptz,
  CHECK (asset_kind <> '')
);

CREATE TABLE studio.asset_revisions (
  revision_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_id uuid NOT NULL REFERENCES studio.asset_heads(asset_id) ON DELETE RESTRICT,
  revision_no integer NOT NULL CHECK(revision_no>=1),
  supersedes_revision_id uuid REFERENCES studio.asset_revisions(revision_id) ON DELETE RESTRICT,
  created_by_actor_ref text NOT NULL,
  payload jsonb,
  payload_storage_ref text,
  content_hash text NOT NULL CHECK(length(content_hash)=64),
  epistemic_class text NOT NULL,
  source_refs jsonb NOT NULL DEFAULT '[]'::jsonb,
  dependency_refs jsonb NOT NULL DEFAULT '[]'::jsonb,
  rights_by_action jsonb NOT NULL DEFAULT '{}'::jsonb,
  content_state text NOT NULL DEFAULT 'SNAPSHOTTED',
  freshness_state text NOT NULL DEFAULT 'CURRENT',
  original_task_id uuid REFERENCES public.research_tasks(task_id) ON DELETE SET NULL,
  -- Immutable origin snapshot MUST include original task_id even if FK later SET NULL.
  origin_task_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,
  provenance jsonb NOT NULL DEFAULT '{}'::jsonb,
  idempotency_key text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(asset_id,revision_no),
  UNIQUE(asset_id,idempotency_key),
  UNIQUE(asset_id,revision_id),
  CHECK ((payload IS NOT NULL) OR (payload_storage_ref IS NOT NULL))
);
ALTER TABLE studio.asset_heads ADD CONSTRAINT asset_head_revision_fkey
  FOREIGN KEY (asset_id,current_revision_id) REFERENCES studio.asset_revisions(asset_id,revision_id)
  DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX asset_revisions_source_task_idx ON studio.asset_revisions(original_task_id);

-- Target table required by current main `data-production-repository.mjs/recordGate`.
-- Live `to_regclass('control.gate_candidates')` is NULL. This is a candidate submission table,
-- NOT a second Gate authority; only an independent reviewer may write control.gate_audits.
CREATE TABLE control.gate_candidates (
  candidate_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  run_id uuid NOT NULL REFERENCES control.production_runs(run_id) ON DELETE RESTRICT,
  stage text NOT NULL CHECK(stage IN ('D00','D01','D02','D03','D04','D05')),
  gate_code text NOT NULL CHECK(gate_code IN ('G0','G1','G2','G3','G4','G5')),
  object_type text NOT NULL,
  object_id uuid NOT NULL,
  artifact_revision text NOT NULL,
  purpose_namespace text NOT NULL,
  purpose_code text NOT NULL,
  purpose_version text NOT NULL,
  allowed_scope jsonb NOT NULL,
  consumer text NOT NULL,
  dependency_snapshot jsonb NOT NULL,
  evidence_refs jsonb NOT NULL,
  input_fingerprint text NOT NULL CHECK(length(input_fingerprint)=64),
  candidate_status text NOT NULL DEFAULT 'SUBMITTED',
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK(jsonb_typeof(dependency_snapshot)='array'),
  CHECK(jsonb_typeof(evidence_refs)='array' AND jsonb_array_length(evidence_refs)>0)
);
-- Production identity is restricted to inserting reviewed candidates only,
-- and MUST NOT be granted INSERT/UPDATE on control.gate_audits.

CREATE TABLE studio.asset_links (
  link_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_revision_id uuid NOT NULL REFERENCES studio.asset_revisions(revision_id) ON DELETE RESTRICT,
  target_kind text NOT NULL,
  target_ref text NOT NULL,
  -- Stable revision or explicit externally anchored version; no vague name-only reuse.
  target_revision_ref text NOT NULL,
  link_role text NOT NULL,
  project_id uuid NOT NULL REFERENCES studio.projects(project_id) ON DELETE RESTRICT,
  rights_decision_ref text NOT NULL,
  evidence_basis jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (length(target_ref)>0)
);
CREATE UNIQUE INDEX studio_asset_link_exact_idx ON studio.asset_links
  (source_revision_id,target_kind,target_ref,COALESCE(target_revision_ref,''),link_role);
CREATE INDEX studio_asset_links_target_idx ON studio.asset_links(target_kind,target_ref);

CREATE TABLE studio.delegations (
  delegation_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  -- Task may be expired/deleted. Preserve lawful immutable task ref+scope snapshot.
  root_task_id uuid REFERENCES public.research_tasks(task_id) ON DELETE SET NULL,
  root_task_ref text NOT NULL,
  root_task_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,
  subtask_ref text NOT NULL,
  delegation_series_id uuid NOT NULL,
  delegation_revision_no int NOT NULL DEFAULT 1 CHECK(delegation_revision_no>=1),
  supersedes_delegation_id uuid REFERENCES studio.delegations(delegation_id) ON DELETE RESTRICT,
  project_id uuid NOT NULL REFERENCES studio.projects(project_id) ON DELETE RESTRICT,
  requester_actor_ref text NOT NULL,
  executor_ref text NOT NULL,
  provider_ref text,
  target_stage text,
  input_manifest jsonb NOT NULL,
  allowed_actions jsonb NOT NULL,
  transfer_rights_decision jsonb NOT NULL,
  budget_limit numeric(14,4),
  request_hash text NOT NULL CHECK(length(request_hash)=64),
  idempotency_key text NOT NULL,
  status text NOT NULL DEFAULT 'REQUESTED',
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(project_id,root_task_ref,idempotency_key), -- stable after root_task_id SET NULL
  UNIQUE(delegation_series_id,delegation_revision_no)
);

CREATE TABLE studio.execution_receipts (
  receipt_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  delegation_id uuid NOT NULL REFERENCES studio.delegations(delegation_id) ON DELETE RESTRICT,
  attempt_no integer NOT NULL CHECK(attempt_no>=1),
  request_hash text NOT NULL,
  result_hash text,
  result_manifest jsonb NOT NULL,
  candidate_refs jsonb NOT NULL DEFAULT '[]'::jsonb,
  acceptance_state text NOT NULL,
  actual_cost numeric(14,4),
  tool_version text,
  finished_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(delegation_id,attempt_no)
);

CREATE TABLE studio.use_events (
  use_event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid REFERENCES studio.projects(project_id) ON DELETE RESTRICT,
  consumer_kind text NOT NULL,
  purpose text NOT NULL,
  action text NOT NULL,
  artifact_kind text NOT NULL,
  artifact_ref text NOT NULL,
  revision_ref text NOT NULL,
  related_task_ref text,
  policy_decision_ref text,
  allowed boolean NOT NULL,
  reason_code text,
  derived_asset_revision_id uuid REFERENCES studio.asset_revisions(revision_id) ON DELETE RESTRICT,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  CHECK (consumer_kind IN ('studio','agent','external_adapter','watch','explore','admin'))
);
CREATE INDEX studio_use_events_target_idx ON studio.use_events(artifact_kind,artifact_ref,revision_ref,occurred_at DESC);

CREATE TABLE experience.runtime_sessions (
  session_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  owner_user_id uuid REFERENCES public.users(user_id) ON DELETE SET NULL,
  consumer_kind text NOT NULL CHECK(consumer_kind IN('watch','explore','studio')),
  legacy_session_ref text,
  work_revision_id uuid REFERENCES publication.work_revisions(revision_id) ON DELETE SET NULL,
  experience_goal jsonb NOT NULL DEFAULT '{}'::jsonb,
  state_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,
  state_revision integer NOT NULL DEFAULT 1,
  access_state text NOT NULL DEFAULT 'RESTRICTED',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK(state_revision>=1)
);
CREATE TABLE experience.runtime_events (
  event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES experience.runtime_sessions(session_id) ON DELETE RESTRICT,
  event_no bigint NOT NULL,
  action text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  related_asset_ref text,
  rights_decision_ref text,
  happened_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(session_id,event_no)
);

CREATE TABLE participation.contributions (
  contribution_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid REFERENCES studio.projects(project_id) ON DELETE RESTRICT,
  contributor_ref text,
  contribution_series_id uuid NOT NULL,
  consent_revision_no integer NOT NULL CHECK(consent_revision_no>=1),
  supersedes_contribution_id uuid REFERENCES participation.contributions(contribution_id) ON DELETE RESTRICT,
  consent_status text NOT NULL CHECK(consent_status IN('GRANTED','WITHDRAWN','UNCONFIRMED')),
  consent_scope jsonb NOT NULL DEFAULT '{}'::jsonb,
  source_ref text,
  payload_ref text,
  rights_by_action jsonb NOT NULL DEFAULT '{}'::jsonb,
  contribution_state text NOT NULL DEFAULT 'CANDIDATE',
  submitted_at timestamptz NOT NULL DEFAULT now(),
  withdrawn_at timestamptz,
  UNIQUE(contribution_series_id,consent_revision_no)
);
-- Every new consent/withdrawal decision is a new row; consumers check latest valid state.

CREATE TABLE culture.trace_candidates (
  trace_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  trace_series_id uuid NOT NULL,
  trace_revision_no integer NOT NULL CHECK(trace_revision_no>=1),
  supersedes_trace_id uuid REFERENCES culture.trace_candidates(trace_id) ON DELETE RESTRICT,
  contribution_id uuid REFERENCES participation.contributions(contribution_id) ON DELETE RESTRICT,
  source_ref text,
  observed_at timestamptz,
  observed_time_precision text,
  spatial_scope jsonb NOT NULL DEFAULT '{}'::jsonb,
  description_candidate jsonb NOT NULL DEFAULT '{}'::jsonb,
  evidence_file_ref text,
  rights_by_action jsonb NOT NULL DEFAULT '{}'::jsonb,
  consent_status text NOT NULL DEFAULT 'UNCONFIRMED',
  review_state text NOT NULL DEFAULT 'RESEARCH_LEAD',
  d00_intake_request_ref text,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(trace_series_id,trace_revision_no)
);

-- In-place source metadata ADAPT, not a second raw-item Truth store.
ALTER TABLE source.raw_items
  ADD COLUMN IF NOT EXISTS storage_state text NOT NULL DEFAULT 'POINTER_UNVERIFIED',
  ADD COLUMN IF NOT EXISTS storage_bucket text,
  ADD COLUMN IF NOT EXISTS storage_object_key text,
  ADD COLUMN IF NOT EXISTS storage_verified_at timestamptz,
  ADD COLUMN IF NOT EXISTS storage_receipt jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE source.raw_items
  ADD CONSTRAINT raw_item_storage_state_check
  CHECK (storage_state IN ('POINTER_UNVERIFIED','PENDING','STORED_VERIFIED','UNAVAILABLE','RIGHTS_BLOCKED','REVOKED'));
ALTER TABLE source.raw_items
  ADD CONSTRAINT raw_item_storage_verified_check
  CHECK (storage_state <> 'STORED_VERIFIED' OR
    (storage_bucket IS NOT NULL AND storage_object_key IS NOT NULL AND storage_verified_at IS NOT NULL));

-- Project binding adaptation for future tasks: old tasks stay UNMAPPED (NULL) until
-- authenticated owner migration confirms correct project; never infer by topic/title.
ALTER TABLE public.research_tasks
  ADD COLUMN IF NOT EXISTS project_id uuid REFERENCES studio.projects(project_id) ON DELETE SET NULL;

