ALTER TABLE studio.asset_revisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE studio.asset_links ENABLE ROW LEVEL SECURITY;
ALTER TABLE studio.delegations ENABLE ROW LEVEL SECURITY;
ALTER TABLE studio.execution_receipts ENABLE ROW LEVEL SECURITY;
ALTER TABLE studio.use_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE experience.runtime_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE experience.runtime_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE participation.contributions ENABLE ROW LEVEL SECURITY;
ALTER TABLE culture.trace_candidates ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA studio,experience,participation,culture FROM PUBLIC,anon,authenticated;

